#include "event_bus.hpp"
#include "event_log.hpp"

#include <cassert>
#include <cstdio>
#include <vector>

static void test_bulk_subscribe_rejects_whole_batch_when_cumulative_exceeds_capacity() {
    EventLog log(10);
    EventBus bus(log, 2);

    std::vector<EventBus::Callback> callbacks = {
        [](const Event&) {}, [](const Event&) {}, [](const Event&) {}
    };
    std::vector<int> outIds;
    int result = bus.bulkSubscribe("topic-a", callbacks, outIds);
    assert(result == 0);
    assert(bus.countSubscribersForTopic("topic-a") == 0);
}

static void test_bulk_subscribe_succeeds_within_capacity() {
    EventLog log(10);
    EventBus bus(log, 3);

    std::vector<EventBus::Callback> callbacks = {
        [](const Event&) {}, [](const Event&) {}
    };
    std::vector<int> outIds;
    int result = bus.bulkSubscribe("topic-a", callbacks, outIds);
    assert(result == 1);
    assert(outIds.size() == 2);
}

int main() {
    test_bulk_subscribe_rejects_whole_batch_when_cumulative_exceeds_capacity();
    test_bulk_subscribe_succeeds_within_capacity();
    printf("PASS\n");
    return 0;
}

