#pragma once

#include <functional>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

#include "event.hpp"
#include "event_log.hpp"

class EventBus {
public:
    using Callback = std::function<void(const Event&)>;

    explicit EventBus(EventLog& log, int maxSubscribersPerTopic = -1)
        : log_(log), maxSubscribersPerTopic_(maxSubscribersPerTopic) {}

    int countSubscribersForTopic(const std::string& topic) const {
        int count = 0;
        for (const auto& entry : subscribers_) {
            if (entry.second.first == topic) {
                count++;
            }
        }
        return count;
    }

    /* Registers a callback for an exact topic match. Returns a
     * subscription id usable with unsubscribe(), or -1 if the topic
     * is already at maxSubscribersPerTopic capacity. */
    int subscribe(const std::string& topic, Callback cb) {
        if (maxSubscribersPerTopic_ >= 0 && countSubscribersForTopic(topic) >= maxSubscribersPerTopic_) {
            return -1;
        }
        int id = next_id_++;
        subscribers_[id] = std::make_pair(topic, std::move(cb));
        return id;
    }

    /* Subscribes every callback in `callbacks` to `topic` in one call.
     * Validates the WHOLE batch against maxSubscribersPerTopic (the
     * topic's current subscriber count plus the batch size) ONCE
     * before subscribing any of them - not each callback individually
     * against a stale pre-batch count. Fills outIds and returns 1 on
     * success, or 0 (nothing subscribed) if the batch would overflow. */
    int bulkSubscribe(const std::string& topic, const std::vector<Callback>& callbacks, std::vector<int>& outIds) {
        if (callbacks.empty()) {
            return 0;
        }
        if (maxSubscribersPerTopic_ >= 0) {
            int current = countSubscribersForTopic(topic);
            if (current + static_cast<int>(callbacks.size()) > maxSubscribersPerTopic_) {
                return 0;
            }
        }
        outIds.clear();
        for (const Callback& cb : callbacks) {
            int id = next_id_++;
            subscribers_[id] = std::make_pair(topic, cb);
            outIds.push_back(id);
        }
        return 1;
    }

    void unsubscribe(int subscription_id) {
        subscribers_.erase(subscription_id);
    }

    /* Records the event in the log, then invokes every subscriber whose
     * topic exactly matches. Returns how many callbacks were invoked. */
    int publish(const std::string& topic, const std::string& payload) {
        Event event{next_seq_++, topic, payload};
        log_.record(event);

        int invoked = 0;
        for (const auto& entry : subscribers_) {
            const std::string& sub_topic = entry.second.first;
            const Callback& cb = entry.second.second;
            if (sub_topic == topic) {
                cb(event);
                invoked++;
            }
        }
        return invoked;
    }

private:
    EventLog& log_;
    int maxSubscribersPerTopic_;
    std::unordered_map<int, std::pair<std::string, Callback>> subscribers_;
    int next_id_ = 1;
    long next_seq_ = 1;
};

